package com.bank.refcode;

import java.util.logging.*;

public class PalindromeDemo {
    private static final Logger log = Logger.getLogger(PalindromeDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        RefCodeValidator validator = new RefCodeValidator();

        String good = "RBI-2a2-IBR"; // core: RBI2a2IBR? check example below
        String palindrome = "A1b2-2b1A"; // alnum: A1b22b1A → palindrome ignoring case
        String bad = "SAV-2001-CUR";

        log.info(() -> "'" + palindrome + "' valid? " + validator.isValidPalindrome(palindrome));
        log.info(() -> "'" + bad + "' valid? " + validator.isValidPalindrome(bad));
        log.info(() -> "'' valid? " + validator.isValidPalindrome(""));
    }
}

