class RefCodeValidator {
    private static final Logger log = Logger.getLogger(RefCodeValidator.class.getName());

    // Opposite-end pointers, skip non-alphanumeric, case-insensitive. O(n), O(1).
    boolean isValidPalindrome(String s) {
        int left = 0, right = s.length() - 1;
        while (left < right) {
            while (left < right && !Character.isLetterOrDigit(s.charAt(left))) left++;
            while (left < right && !Character.isLetterOrDigit(s.charAt(right))) right--;
            char lc = Character.toLowerCase(s.charAt(left));
            char rc = Character.toLowerCase(s.charAt(right));
            if (lc != rc) {
                log.warning(() -> "Mismatch at " + left + "/" + right);
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}

